372	          !TestSessionUtil.hasState(row.testState, 'CONTROLLER', 'TERMINATED') &&
373	          (TestSessionUtil.hasState(row.testState, 'CONNECTION', 'POLLING') ||
374	            TestSessionUtil.hasState(row.testState, 'CONNECTION', 'WEBSOCKET')))
375	          .map(row => row.testId);
