386	  sortSessions(sort: Sort, sessions: TestSession[]): TestSession[] {
387	    return sessions
388	      .sort((session1, session2) => {
389	        const sortDirectionFactor = (sort.direction === 'asc' ? 1 : -1);
390	        if (sort.active === 'timestamp') {
391	          return (session1.data.timestamp - session2.data.timestamp) * sortDirectionFactor;
392	        }
393	        if (sort.active === '_checked') {
394	          const session1isChecked = this.isChecked(session1);
395	          const session2isChecked = this.isChecked(session2);
396	          if (!session1isChecked && session2isChecked) {
397	            return 1 * sortDirectionFactor;
398	          }
399	          if (session1isChecked && !session2isChecked) {
400	            return -1 * sortDirectionFactor;
401	          }
402	          return 0;
403	        }
404	        if (sort.active === '_superState') {
405	          return (TestSessionsSuperStates.indexOf(session1.state) -
406	            TestSessionsSuperStates.indexOf(session2.state)) * sortDirectionFactor;
407	        }
408	        if (sort.active === '_currentBlock') {
409	          const s1curBlock = session1.current?.ancestor?.blockId ?? 'zzzzzzzzzz';
410	          const s2curBlock = session2.current?.ancestor?.blockId ?? 'zzzzzzzzzz';
411	          return s1curBlock.localeCompare(s2curBlock) * sortDirectionFactor;
412	        }
413	        if (sort.active === '_currentUnit') {
414	          const s1currentUnit = session1.current?.unit?.label ?? 'zzzzzzzzzz';
415	          const s2currentUnit = session2.current?.unit?.label ?? 'zzzzzzzzzz';
416	          return s1currentUnit.localeCompare(s2currentUnit) * sortDirectionFactor;
417	        }
418	        if (sort.active.startsWith('bookletState:')) {
419	          const bookletState = sort.active.replace('bookletState:', '');
420	          const label = (session: TestSession): string =>
421	            TestSessionUtil.bookletStateLabel(session, bookletState) ?? 'zzzzzzzzzz';
422	          const a = label(session1);
423	          const b = label(session2);
424	          return a.localeCompare(b) * sortDirectionFactor;
425	        }
426	        let valA = session1.data[sort.active as keyof typeof session1.data] ?? 'zzzzzzzzzz';
427	        let valB = session2.data[sort.active as keyof typeof session2.data] ?? 'zzzzzzzzzz';
428	        if (typeof valA === 'number') {
429	          valA = valA.toString(10);
430	        }
431	        if (typeof valB === 'number') {
432	          valB = valB.toString(10);
433	        }
434	        if ((typeof valA === 'object') || (typeof valB === 'object')) {
435	          return 0;
436	        }
437	        return valA.localeCompare(valB) * sortDirectionFactor;
438	      });
439	  }
